import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.44aEvdQQ.js";const h=JSON.parse('{"title":"Project Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/projects.md","filePath":"reference/tools/projects.md"}'),d={name:"reference/tools/projects.md"};function s(c,t,n,i,l,_){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="project-tools" tabindex="-1">Project Tools <a class="header-anchor" href="#project-tools" aria-label="Permalink to &quot;Project Tools&quot;">​</a></h1><hr><h2 id="create_project" tabindex="-1">create_project <a class="header-anchor" href="#create_project" aria-label="Permalink to &quot;create_project {#create_project}&quot;">​</a></h2><p>Create a new project. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>02. Projects</code>, <code>22. Projects Master</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td>Unique project name</td></tr><tr><td><code>project_type</code></td><td>✅</td><td><code>&quot;Retainer&quot;</code> | <code>&quot;T&amp;M&quot;</code> | <code>&quot;Fixed Price&quot;</code> | <code>&quot;Pro Bono&quot;</code> | <code>&quot;Agile&quot;</code> — never defaulted</td></tr><tr><td><code>client_name</code></td><td>✅</td><td>Client org — created automatically if new</td></tr><tr><td><code>contract_value</code></td><td>Cond.</td><td>Required for Fixed Price</td></tr><tr><td><code>hours_budget</code></td><td>Cond.</td><td>Required for Retainer (annual hours). Optional for others.</td></tr><tr><td><code>billing_rate</code></td><td></td><td>Hourly rate billed to client</td></tr><tr><td><code>deadline</code></td><td></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>notes</code></td><td></td><td></td></tr><tr><td><code>project_category</code></td><td></td><td>Defaults to <code>&quot;client&quot;</code></td></tr></tbody></table><p><strong>Rules:</strong></p><ul><li>Never assume a default project type — always ask</li><li>For Agile parents: no contract_value or hours_budget on the parent itself</li><li>After Agile parent creation, offer to set up Sprint 1</li></ul><hr><h2 id="delete_project" tabindex="-1">delete_project <a class="header-anchor" href="#delete_project" aria-label="Permalink to &quot;delete_project {#delete_project}&quot;">​</a></h2><p>Delete a project. All entries are reassigned to a fallback project. <strong>Owner only.</strong></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td>Project to delete</td></tr><tr><td><code>reassign_to</code></td><td>✅</td><td>Project to move existing time entries to</td></tr></tbody></table><hr><h2 id="rename_project" tabindex="-1">rename_project <a class="header-anchor" href="#rename_project" aria-label="Permalink to &quot;rename_project {#rename_project}&quot;">​</a></h2><p>Rename a project and update all references. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>02. Projects</code>, <code>22. Projects Master</code>, <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>old_name</code></td><td>✅</td><td></td></tr><tr><td><code>new_name</code></td><td>✅</td><td></td></tr></tbody></table><hr><h2 id="list_projects" tabindex="-1">list_projects <a class="header-anchor" href="#list_projects" aria-label="Permalink to &quot;list_projects {#list_projects}&quot;">​</a></h2><p>List all projects (filtered by role).</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>04. Clients</code></p><p><strong>Returns</strong>: name, client, type, status, deadline (Owner/Manager only), PM</p><hr><h2 id="get_project_info" tabindex="-1">get_project_info <a class="header-anchor" href="#get_project_info" aria-label="Permalink to &quot;get_project_info {#get_project_info}&quot;">​</a></h2><p>Full project details. Always call this first when checking project status — it tells you the type, which determines whether to follow up with <code>get_project_status</code> or <code>get_retainer_status</code>.</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>22. Projects Master</code>, <code>04. Clients</code>, <code>03. Users</code></p><p><strong>Returns</strong>: name, client, type, budget_hours, status, pm_name, deadline (Owner/Manager), contract_value (Owner), billing_rate (Owner)</p><hr><h2 id="get_project_status" tabindex="-1">get_project_status <a class="header-anchor" href="#get_project_status" aria-label="Permalink to &quot;get_project_status {#get_project_status}&quot;">​</a></h2><p>Task-level budget status for <strong>non-retainer</strong> projects.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>06. Project_Tasks</code>, <code>02. Projects</code></p><p><strong>Returns per task</strong>: hours_logged, budget_hours, % used, alert status, committed hours (logged + allocated)</p><p><strong>Do not use for retainers</strong> — use <code>get_retainer_status</code> instead.</p><hr><h2 id="get_project_health" tabindex="-1">get_project_health <a class="header-anchor" href="#get_project_health" aria-label="Permalink to &quot;get_project_health {#get_project_health}&quot;">​</a></h2><p>Burn rate health for <strong>retainer</strong> projects, with envelope-aware forecast.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>07. Budgets</code>, <code>22. Projects Master</code></p><p><strong>Returns</strong>: hours_logged, days_elapsed, pace_per_day, projected_eom_hours, allocated_remaining, forecast_with_allocations, variance, utilisation%, status</p><p><strong>Status values</strong>: <code>critical_overpace</code>, <code>warning_overpace</code>, <code>on_track</code>, <code>warning_underpace</code>, <code>critical_underpace</code></p><hr><h2 id="get_my_projects" tabindex="-1">get_my_projects <a class="header-anchor" href="#get_my_projects" aria-label="Permalink to &quot;get_my_projects {#get_my_projects}&quot;">​</a></h2><p>Projects where the requesting user is the PM (or all projects if Owner).</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="set_project_budget" tabindex="-1">set_project_budget <a class="header-anchor" href="#set_project_budget" aria-label="Permalink to &quot;set_project_budget {#set_project_budget}&quot;">​</a></h2><p>Set the project-level hours budget (Tier 1). <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>02. Projects</code> col D</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>budget_hours</code></td><td>✅</td><td>Total hours cap</td></tr></tbody></table><hr><h2 id="set_project_deadline" tabindex="-1">set_project_deadline <a class="header-anchor" href="#set_project_deadline" aria-label="Permalink to &quot;set_project_deadline {#set_project_deadline}&quot;">​</a></h2><p>Set the project delivery date. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>02. Projects</code> col I</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>deadline</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr></tbody></table><hr><h2 id="list_tasks" tabindex="-1">list_tasks <a class="header-anchor" href="#list_tasks" aria-label="Permalink to &quot;list_tasks {#list_tasks}&quot;">​</a></h2><p>All task types with billability flag.</p><p><strong>Reads from</strong>: <code>05. Tasks</code></p><hr><h2 id="create_task" tabindex="-1">create_task <a class="header-anchor" href="#create_task" aria-label="Permalink to &quot;create_task {#create_task}&quot;">​</a></h2><p>Create a new global task type. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>task_name</code>, <code>is_billable</code> (true/false)</p><hr><h2 id="rename_task" tabindex="-1">rename_task <a class="header-anchor" href="#rename_task" aria-label="Permalink to &quot;rename_task {#rename_task}&quot;">​</a></h2><p>Rename a task type globally. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>old_name</code>, <code>new_name</code></p><hr><h2 id="delete_task" tabindex="-1">delete_task <a class="header-anchor" href="#delete_task" aria-label="Permalink to &quot;delete_task {#delete_task}&quot;">​</a></h2><p>Delete a task type. <strong>Owner only.</strong></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>task_name</code></td><td>✅</td><td></td></tr><tr><td><code>reassign_to</code></td><td></td><td>Task to reassign existing entries to</td></tr></tbody></table><hr><h2 id="get_project_tasks" tabindex="-1">get_project_tasks <a class="header-anchor" href="#get_project_tasks" aria-label="Permalink to &quot;get_project_tasks {#get_project_tasks}&quot;">​</a></h2><p>All enabled tasks for a project, with budget and hours logged.</p><p><strong>Reads from</strong>: <code>06. Project_Tasks</code>, <code>05. Tasks</code>, <code>01. Time Entries</code></p><p><strong>Returns per task</strong>: task_name, is_billable, budget_hours, alert_threshold, hours_logged, % used, budget_summary</p><p><strong>budget_summary includes:</strong></p><ul><li><code>tasks_without_budget</code>: count of enabled tasks with no budget set</li><li><code>over_project_budget</code>: whether task totals exceed the project budget</li><li><code>unallocated_hours</code>: project budget minus sum of task budgets</li></ul><hr><h2 id="enable_task_for_project" tabindex="-1">enable_task_for_project <a class="header-anchor" href="#enable_task_for_project" aria-label="Permalink to &quot;enable_task_for_project {#enable_task_for_project}&quot;">​</a></h2><p>Enable a task on a project with optional budget. <strong>Owner or project PM.</strong></p><p><strong>Writes to</strong>: <code>06. Project_Tasks</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>task_name</code></td><td>✅</td><td></td></tr><tr><td><code>budget_hours</code></td><td></td><td>Optional hours budget for this task</td></tr><tr><td><code>alert_threshold</code></td><td></td><td>Percent — defaults to 80</td></tr></tbody></table><hr><h2 id="disable_task_for_project" tabindex="-1">disable_task_for_project <a class="header-anchor" href="#disable_task_for_project" aria-label="Permalink to &quot;disable_task_for_project {#disable_task_for_project}&quot;">​</a></h2><p>Disable a task on a project (deletes the row from <code>06. Project_Tasks</code>). <strong>Owner or project PM.</strong></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code>, <code>task_name</code></p><hr><h2 id="get_retainer_status" tabindex="-1">get_retainer_status <a class="header-anchor" href="#get_retainer_status" aria-label="Permalink to &quot;get_retainer_status {#get_retainer_status}&quot;">​</a></h2><p>Monthly burn rate for a retainer project. See <a href="/vera-docs/reference/concepts/retainers.html">Retainers</a> for interpretation guide.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>07. Budgets</code>, <code>22. Projects Master</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code></p><p><strong>Returns</strong>: budget_hours, hours_logged, hours_remaining, days_elapsed, days_remaining, pace_per_day, projected_eom_hours, allocated_remaining, forecast_with_allocations, variance, utilisation_percent, exceed_date, unused_hours, unused_value, status</p><hr><h2 id="get_pm_retainer_summary" tabindex="-1">get_pm_retainer_summary <a class="header-anchor" href="#get_pm_retainer_summary" aria-label="Permalink to &quot;get_pm_retainer_summary {#get_pm_retainer_summary}&quot;">​</a></h2><p>All retainer projects assigned to a PM, with burn status for each. <strong>Manager/Owner.</strong></p><hr><h2 id="create_sprint" tabindex="-1">create_sprint <a class="header-anchor" href="#create_sprint" aria-label="Permalink to &quot;create_sprint {#create_sprint}&quot;">​</a></h2><p>Create a new sprint under an Agile parent. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>02. Projects</code>, <code>22. Projects Master</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>parent_project_name</code></td><td>✅</td><td>The Agile parent project</td></tr><tr><td><code>contract_value</code></td><td>✅</td><td>Must be asked explicitly — never derived</td></tr><tr><td><code>hours_budget</code></td><td>✅</td><td>Sprint hours estimate</td></tr></tbody></table><p>Sprint number is auto-incremented — do not specify manually.</p><hr><h2 id="get_agile_summary" tabindex="-1">get_agile_summary <a class="header-anchor" href="#get_agile_summary" aria-label="Permalink to &quot;get_agile_summary {#get_agile_summary}&quot;">​</a></h2><p>All sprints under an Agile project with revenue recognition.</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>01. Time Entries</code>, <code>22. Projects Master</code></p><p><strong>Returns per sprint</strong>: sprint_name, sprint_number, status, contract_value (Owner), hours_budget, hours_logged, recognised_revenue (Owner)</p><hr><h2 id="update_sprint_status" tabindex="-1">update_sprint_status <a class="header-anchor" href="#update_sprint_status" aria-label="Permalink to &quot;update_sprint_status {#update_sprint_status}&quot;">​</a></h2><p>Transition a sprint from <code>planned</code> to <code>active</code>. <strong>Owner only.</strong> No confirmation prompt needed.</p><p><strong>Updates</strong>: <code>02. Projects</code> col L</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>sprint_id</code>, <code>new_status</code> (<code>&quot;active&quot;</code>)</p>',120)])])}const u=e(d,[["render",s]]);export{h as __pageData,u as default};
